import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import axios from 'axios';
import { 
  Heart, 
  MessageCircle, 
  Share2, 
  Users,
  Briefcase,
  Trophy,
  TrendingUp,
  Calendar,
  Award,
  Bell,
  Trash2,
  Sparkles,
  Target,
  Zap,
  Star,
  ArrowRight,
  Plus
} from 'lucide-react';
import toast from 'react-hot-toast';

const Dashboard = () => {
  const { user } = useAuth();
  const [posts, setPosts] = useState([]);
  const [recentJobs, setRecentJobs] = useState([]);
  const [recentCompetitions, setRecentCompetitions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [newPost, setNewPost] = useState('');
  const [showCreatePost, setShowCreatePost] = useState(false);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const [postsRes, jobsRes, competitionsRes] = await Promise.all([
        axios.get('/api/posts?limit=5'),
        axios.get('/api/jobs?limit=3'),
        axios.get('/api/competitions?limit=3')
      ]);

      setPosts(postsRes.data.posts || []);
      setRecentJobs(jobsRes.data.jobs || []);
      setRecentCompetitions(competitionsRes.data.competitions || []);
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleCreatePost = async (e) => {
    e.preventDefault();
    if (!newPost.trim()) return;

    try {
      const response = await axios.post('/api/posts', {
        description: newPost
      });

      setPosts([response.data, ...posts]);
      setNewPost('');
      setShowCreatePost(false);
      toast.success('Post created successfully!');
    } catch (error) {
      toast.error('Failed to create post');
    }
  };

  const handleLikePost = async (postId) => {
    try {
      const response = await axios.put(`/api/posts/${postId}/like`);
      setPosts(posts.map(post => 
        post._id === postId ? response.data : post
      ));
    } catch (error) {
      toast.error('Failed to like post');
    }
  };

  const handleDeletePost = async (postId) => {
    if (!window.confirm('Are you sure you want to delete this post?')) {
      return;
    }

    try {
      await axios.delete(`/api/posts/${postId}`);
      setPosts(posts.filter(post => post._id !== postId));
      toast.success('Post deleted successfully!');
    } catch (error) {
      toast.error('Failed to delete post');
    }
  };

  const formatDate = (date) => {
    return new Date(date).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-centurion-600"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-indigo-50 to-purple-50">
      {/* Hero Section */}
      <div className="relative overflow-hidden bg-gradient-to-r from-blue-600 via-purple-600 to-indigo-700">
        <div className="absolute inset-0 bg-black opacity-10"></div>
        <div className="absolute inset-0">
          <div className="absolute top-0 left-0 w-72 h-72 bg-white opacity-5 rounded-full -translate-x-1/2 -translate-y-1/2 animate-pulse"></div>
          <div className="absolute bottom-0 right-0 w-96 h-96 bg-white opacity-5 rounded-full translate-x-1/2 translate-y-1/2 animate-pulse delay-1000"></div>
        </div>
        <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16">
          <div className="text-center">
            <div className="flex justify-center mb-6">
              <div className="p-4 bg-white bg-opacity-20 rounded-full backdrop-blur-sm">
                <Sparkles className="h-12 w-12 text-white animate-bounce" />
              </div>
            </div>
            <h1 className="text-4xl md:text-6xl font-bold text-white mb-4 animate-fade-in">
              Welcome back, <span className="bg-gradient-to-r from-yellow-300 to-orange-300 bg-clip-text text-transparent">{user?.name}</span>!
            </h1>
            <p className="text-xl text-blue-100 mb-8 max-w-2xl mx-auto">
              {user?.role === 'student' && '🚀 Discover amazing opportunities and showcase your incredible talents'}
              {user?.role === 'faculty' && '🎯 Manage competitions and inspire the next generation'}
              {user?.role === 'recruiter' && '💎 Find exceptional talent for your opportunities'}
            </p>
            <div className="flex justify-center space-x-4">
              <div className="bg-white bg-opacity-20 backdrop-blur-sm rounded-lg px-6 py-3 text-white">
                <div className="flex items-center space-x-2">
                  <Target className="h-5 w-5" />
                  <span className="font-medium">Ready to achieve more?</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 -mt-8 relative z-10">

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main Content */}
        <div className="lg:col-span-2 space-y-6">
          {/* Create Post Section */}
          {!showCreatePost ? (
            <div className="bg-white rounded-2xl shadow-xl border-0 p-6 backdrop-blur-sm bg-opacity-95 hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-1">
              <button
                onClick={() => setShowCreatePost(true)}
                className="w-full text-left p-4 bg-gradient-to-r from-blue-50 to-purple-50 rounded-xl hover:from-blue-100 hover:to-purple-100 transition-all duration-300 flex items-center space-x-4 group"
              >
                <div className="w-12 h-12 bg-gradient-to-r from-blue-500 to-purple-600 rounded-full flex items-center justify-center shadow-lg group-hover:scale-110 transition-transform duration-300">
                  <span className="text-white font-bold text-lg">
                    {user?.name?.charAt(0).toUpperCase()}
                  </span>
                </div>
                <div className="flex-1">
                  <span className="text-gray-600 text-lg">✨ Share your achievements, projects, or thoughts...</span>
                </div>
                <Plus className="h-6 w-6 text-blue-500 group-hover:rotate-90 transition-transform duration-300" />
              </button>
            </div>
          ) : (
            <div className="bg-white rounded-2xl shadow-xl border-0 p-8 backdrop-blur-sm bg-opacity-95">
              <form onSubmit={handleCreatePost}>
                <div className="relative">
                  <textarea
                    value={newPost}
                    onChange={(e) => setNewPost(e.target.value)}
                    placeholder="💭 What's inspiring you today?"
                    className="w-full p-4 border-2 border-gray-200 rounded-xl focus:outline-none focus:ring-4 focus:ring-blue-100 focus:border-blue-400 resize-none text-lg transition-all duration-300"
                    rows="4"
                    autoFocus
                  />
                  <div className="absolute bottom-3 right-3 text-sm text-gray-400">
                    {newPost.length}/500
                  </div>
                </div>
                <div className="flex justify-between items-center mt-6">
                  <button
                    type="button"
                    onClick={() => {
                      setShowCreatePost(false);
                      setNewPost('');
                    }}
                    className="px-6 py-3 text-gray-600 hover:text-gray-800 transition-all duration-300 rounded-lg hover:bg-gray-100"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    disabled={!newPost.trim()}
                    className="px-8 py-3 bg-gradient-to-r from-blue-500 to-purple-600 text-white rounded-xl hover:from-blue-600 hover:to-purple-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-300 transform hover:scale-105 shadow-lg hover:shadow-xl flex items-center space-x-2"
                  >
                    <Zap className="h-5 w-5" />
                    <span>Share Post</span>
                  </button>
                </div>
              </form>
            </div>
          )}

          {/* Posts Feed */}
          <div className="space-y-8">
            <div className="flex items-center justify-between">
              <h2 className="text-2xl font-bold text-gray-900 flex items-center">
                <div className="p-2 bg-gradient-to-r from-orange-400 to-pink-500 rounded-lg mr-3">
                  <TrendingUp className="h-6 w-6 text-white" />
                </div>
                Recent Posts
              </h2>
              <div className="flex items-center space-x-2 text-sm text-gray-500">
                <Star className="h-4 w-4 text-yellow-500" />
                <span>Latest updates from your network</span>
              </div>
            </div>

            {posts.length === 0 ? (
              <div className="bg-white rounded-2xl shadow-xl border-0 p-12 text-center backdrop-blur-sm bg-opacity-95">
                <div className="w-24 h-24 bg-gradient-to-r from-blue-100 to-purple-100 rounded-full flex items-center justify-center mx-auto mb-6">
                  <MessageCircle className="h-12 w-12 text-blue-500" />
                </div>
                <h3 className="text-xl font-semibold text-gray-900 mb-2">No posts yet!</h3>
                <p className="text-gray-500 mb-6">Be the first to share something amazing with the community! 🚀</p>
                <button
                  onClick={() => setShowCreatePost(true)}
                  className="px-6 py-3 bg-gradient-to-r from-blue-500 to-purple-600 text-white rounded-xl hover:from-blue-600 hover:to-purple-700 transition-all duration-300 transform hover:scale-105 shadow-lg"
                >
                  Create First Post
                </button>
              </div>
            ) : (
              posts.map((post) => (
                <div key={post._id} className="bg-white rounded-2xl shadow-xl border-0 p-8 backdrop-blur-sm bg-opacity-95 hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-1">
                  <div className="flex items-start space-x-4">
                    <div className="w-14 h-14 bg-gradient-to-r from-blue-500 to-purple-600 rounded-full flex items-center justify-center shadow-lg ring-4 ring-white">
                      <span className="text-white font-bold text-lg">
                        {post.user?.name?.charAt(0).toUpperCase()}
                      </span>
                    </div>
                    <div className="flex-1">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center space-x-3">
                          <h3 className="font-bold text-gray-900 text-lg">{post.user?.name}</h3>
                          <span className="px-3 py-1 bg-gradient-to-r from-blue-100 to-purple-100 text-blue-700 text-sm font-medium rounded-full capitalize">{post.user?.role}</span>
                          <span className="text-sm text-gray-400">•</span>
                          <span className="text-sm text-gray-500 font-medium">{formatDate(post.createdAt)}</span>
                        </div>
                        {post.user?._id === user?.id && (
                          <button
                            onClick={() => handleDeletePost(post._id)}
                            className="text-gray-400 hover:text-red-500 transition-all duration-300 p-2 rounded-lg hover:bg-red-50 transform hover:scale-110"
                            title="Delete post"
                          >
                            <Trash2 className="h-5 w-5" />
                          </button>
                        )}
                      </div>
                      <p className="text-gray-700 mt-4 text-lg leading-relaxed">{post.description}</p>

                      <div className="flex items-center space-x-8 mt-6 pt-6 border-t border-gray-100">
                        <button
                          onClick={() => handleLikePost(post._id)}
                          className={`flex items-center space-x-3 px-4 py-2 rounded-xl transition-all duration-300 transform hover:scale-105 ${
                            post.likes?.some(like => like.user === user?.id)
                              ? 'text-red-600 bg-red-50 hover:bg-red-100'
                              : 'text-gray-500 hover:text-red-600 hover:bg-red-50'
                          }`}
                        >
                          <Heart className={`h-5 w-5 ${
                            post.likes?.some(like => like.user === user?.id) ? 'fill-current' : ''
                          }`} />
                          <span className="font-medium">{post.likes?.length || 0}</span>
                        </button>
                        <button className="flex items-center space-x-3 px-4 py-2 rounded-xl text-gray-500 hover:text-blue-600 hover:bg-blue-50 transition-all duration-300 transform hover:scale-105">
                          <MessageCircle className="h-5 w-5" />
                          <span className="font-medium">{post.comments?.length || 0}</span>
                        </button>
                        <button className="flex items-center space-x-3 px-4 py-2 rounded-xl text-gray-500 hover:text-green-600 hover:bg-green-50 transition-all duration-300 transform hover:scale-105">
                          <Share2 className="h-5 w-5" />
                          <span className="font-medium">Share</span>
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Sidebar */}
        <div className="space-y-8">
          {/* Quick Stats */}
          <div className="bg-white rounded-2xl shadow-xl border-0 p-8 backdrop-blur-sm bg-opacity-95">
            <h3 className="text-2xl font-bold text-gray-900 mb-6 flex items-center">
              <div className="p-2 bg-gradient-to-r from-green-400 to-blue-500 rounded-lg mr-3">
                <Target className="h-6 w-6 text-white" />
              </div>
              Quick Overview
            </h3>
            <div className="space-y-6">
              <div className="bg-gradient-to-r from-blue-50 to-indigo-50 rounded-xl p-4 hover:from-blue-100 hover:to-indigo-100 transition-all duration-300">
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-3">
                    <div className="p-2 bg-blue-500 rounded-lg">
                      <Briefcase className="h-5 w-5 text-white" />
                    </div>
                    <span className="font-medium text-gray-700">Available Jobs</span>
                  </div>
                  <span className="text-2xl font-bold text-blue-600">{recentJobs.length}</span>
                </div>
              </div>
              <div className="bg-gradient-to-r from-yellow-50 to-orange-50 rounded-xl p-4 hover:from-yellow-100 hover:to-orange-100 transition-all duration-300">
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-3">
                    <div className="p-2 bg-yellow-500 rounded-lg">
                      <Trophy className="h-5 w-5 text-white" />
                    </div>
                    <span className="font-medium text-gray-700">Active Competitions</span>
                  </div>
                  <span className="text-2xl font-bold text-yellow-600">{recentCompetitions.length}</span>
                </div>
              </div>
              <div className="bg-gradient-to-r from-purple-50 to-pink-50 rounded-xl p-4 hover:from-purple-100 hover:to-pink-100 transition-all duration-300">
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-3">
                    <div className="p-2 bg-purple-500 rounded-lg">
                      <Users className="h-5 w-5 text-white" />
                    </div>
                    <span className="font-medium text-gray-700">Your Skills</span>
                  </div>
                  <span className="text-2xl font-bold text-purple-600">{user?.skills?.length || 0}</span>
                </div>
              </div>
            </div>
          </div>

          {/* Recent Jobs */}
          {recentJobs.length > 0 && (
            <div className="bg-white rounded-2xl shadow-xl border-0 p-8 backdrop-blur-sm bg-opacity-95">
              <h3 className="text-2xl font-bold text-gray-900 mb-6 flex items-center">
                <div className="p-2 bg-gradient-to-r from-blue-400 to-cyan-500 rounded-lg mr-3">
                  <Briefcase className="h-6 w-6 text-white" />
                </div>
                Recent Opportunities
              </h3>
              <div className="space-y-4">
                {recentJobs.slice(0, 3).map((job) => (
                  <div key={job._id} className="bg-gradient-to-r from-blue-50 to-cyan-50 rounded-xl p-4 border-l-4 border-blue-500 hover:from-blue-100 hover:to-cyan-100 transition-all duration-300 transform hover:scale-105">
                    <h4 className="font-bold text-gray-900 text-lg mb-2">{job.title}</h4>
                    <p className="text-blue-600 font-medium mb-1">{job.company}</p>
                    <div className="flex items-center space-x-2">
                      <span className="px-3 py-1 bg-blue-100 text-blue-700 text-sm font-medium rounded-full capitalize">{job.type}</span>
                      <ArrowRight className="h-4 w-4 text-blue-500" />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Recent Competitions */}
          {recentCompetitions.length > 0 && (
            <div className="bg-white rounded-2xl shadow-xl border-0 p-8 backdrop-blur-sm bg-opacity-95">
              <h3 className="text-2xl font-bold text-gray-900 mb-6 flex items-center">
                <div className="p-2 bg-gradient-to-r from-yellow-400 to-orange-500 rounded-lg mr-3">
                  <Trophy className="h-6 w-6 text-white" />
                </div>
                Upcoming Competitions
              </h3>
              <div className="space-y-4">
                {recentCompetitions.slice(0, 3).map((competition) => (
                  <div key={competition._id} className="bg-gradient-to-r from-yellow-50 to-orange-50 rounded-xl p-4 border-l-4 border-yellow-500 hover:from-yellow-100 hover:to-orange-100 transition-all duration-300 transform hover:scale-105">
                    <h4 className="font-bold text-gray-900 text-lg mb-2">{competition.title}</h4>
                    <div className="flex items-center space-x-2 mb-2">
                      <Calendar className="h-4 w-4 text-yellow-600" />
                      <p className="text-yellow-600 font-medium">{formatDate(competition.date)}</p>
                    </div>
                    <div className="flex items-center space-x-2">
                      <span className="px-3 py-1 bg-yellow-100 text-yellow-700 text-sm font-medium rounded-full capitalize">{competition.category}</span>
                      <ArrowRight className="h-4 w-4 text-yellow-500" />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
      </div>
    </div>
  );
};

export default Dashboard;
